"""v2.1: more vegetarian and vegan mains, and baking by grams."""
import itertools
from v21lib import R
V, BK = "91-v21-vegetarian-vegan.txt", "92-v21-baking-grams.txt"

# vegan coconut curries: vegetable combo x curry style
VC = [("Sweet Potato and Spinach", "2|sweet potatoes, cubed; 150 g|spinach"), ("Cauliflower and Pea", "1|cauliflower, florets; 200 g|peas, frozen"),
      ("Eggplant and Chickpea", "1|eggplant, cubed; 400 g|chickpeas, drained"), ("Pumpkin and Lentil", "600 g|pumpkin, cubed; 150 g|red lentils"),
      ("Mushroom and Bok Choy", "400 g|mushrooms, sliced; 300 g|bok choy, chopped"), ("Potato and Green Bean", "500 g|potatoes, cubed; 200 g|green beans")]
CS = [("Thai Yellow", "Thai", "3 tbsp|yellow curry paste; 1 tbsp|soy sauce; 1|lime"), ("Sri Lankan", "Sri Lankan", "2 tbsp|curry powder, roasted sri lankan; 1|cinnamon stick; 10|curry leaves"),
      ("Kerala-Style", "South Indian", "1 tsp|mustard seeds; 10|curry leaves; 1 tsp|turmeric; 1|green chili, slit")]
for (vn, ving), (cn, cu, cing) in itertools.product(VC, CS):
    R(V, "%s %s Coconut Curry" % (cn, vn), "Main", cu, 15, 30, 4, "Dinner, Main dish",
      ving + "; 1|onion, chopped; 3|garlic cloves; 2 cm|ginger, grated; 2 tbsp|vegetable oil; 400 ml|coconut milk; 250 ml|vegetable stock; " + cing,
      ["Heat the oil and fry any seeds, leaves or curry paste for 1 minute, then add the onion and cook 6 minutes until soft",
       "Add the garlic, ginger and spices and cook 1 minute",
       "Add the firmer vegetables (and lentils), the coconut milk and stock with 1 tsp salt. Simmer 15 to 20 minutes until tender",
       "Add the leafy greens, peas or beans for the last 5 minutes. Finish with lime if using and serve with rice"])
# grain bowls
for t, cu, ings, st in [
    ("Roasted Chickpea Shawarma Bowls", "Levantine", "800 g|chickpeas, drained; 2 tsp|shawarma spice; 2 tbsp|olive oil; 200 g|bulgur wheat; 1|cucumber; 2|tomatoes; 4 tbsp|tahini; 1|lemon", "Roast the chickpeas with the oil, spice and salt at 210 °C for 25 minutes / Cook the bulgur / Thin the tahini with lemon and water / Build bowls with bulgur, chopped salad, chickpeas and tahini"),
    ("Miso Glazed Tofu Rice Bowls", "Japanese", "400 g|firm tofu, sliced; 2 tbsp|white miso; 1 tbsp|maple syrup; 1 tbsp|rice vinegar; 300 g|rice; 1|cucumber; 200 g|edamame", "Start the rice. Mix the miso, maple and vinegar / Fry the tofu until golden, brush with the glaze and cook 1 minute more per side / Serve over rice with cucumber and edamame"),
    ("Black Bean Burrito Bowls", "Tex-Mex", "800 g|black beans, drained; 300 g|rice; 200 g|corn kernels; 1|avocado; 150 g|salsa; 1|lime; 1 tsp|cumin", "Cook the rice and stir in lime juice / Warm the beans with cumin and salt / Build bowls with rice, beans, corn, avocado and salsa"),
    ("Lentil Tabbouleh Bowls", "Lebanese", "200 g|green lentils; 1 large handful|parsley; 1 handful|mint; 3|tomatoes; 1|cucumber; 2|lemons; 4 tbsp|olive oil", "Simmer the lentils 20 to 25 minutes until just tender; drain / Chop the herbs, tomatoes and cucumber finely / Toss everything with lemon juice, oil and salt"),
    ("Sesame Soba Noodle Bowls", "Japanese", "250 g|soba noodles; 2 tbsp|tahini; 2 tbsp|soy sauce; 1 tbsp|rice vinegar; 1 tbsp|maple syrup; 1|carrot, cut into matchsticks; 200 g|edamame; 2|spring onions", "Cook the soba, rinse in cold water / Whisk the tahini, soy, vinegar and maple with 2 tbsp water / Toss the noodles with the sauce and vegetables"),
    ("Harissa Roasted Vegetable Couscous", "Tunisian", "250 g|couscous; 2|bell peppers; 2|zucchini; 1|red onion; 2 tbsp|harissa paste; 3 tbsp|olive oil; 400 g|chickpeas, drained", "Roast the chopped vegetables and chickpeas with the harissa and oil at 210 °C for 25 minutes / Pour 300 ml boiling water over the couscous, cover 5 minutes and fluff / Toss together"),
    ("Peanut Tempeh Noodle Bowls", "Indonesian", "250 g|tempeh, sliced; 200 g|rice noodles; 3 tbsp|peanut butter; 2 tbsp|soy sauce; 1|lime; 1 tbsp|maple syrup; 1|cucumber; 1|carrot", "Fry the tempeh until golden / Soak the noodles / Whisk the peanut butter, soy, lime and maple with warm water / Toss everything together"),
    ("Mediterranean Quinoa Bowls with Feta", "Greek", "200 g|quinoa; 1|cucumber; 200 g|cherry tomatoes; 80 g|kalamata olives; 150 g|feta; 1|lemon; 3 tbsp|olive oil", "Cook the quinoa and cool slightly / Chop the vegetables / Toss with olives, lemon, oil and salt and crumble over the feta"),
]:
    R(V, t, "Main", cu, 15, 25, 4, "Lunch, Dinner, Main dish", ings, st)
# bean burgers & patties, bakes, stuffed veg, pastas
for t, cu, ings, st, cook in [
    ("Chickpea and Sweet Potato Patties", "Indian", "400 g|chickpeas, drained; 1|sweet potato, baked; 60 g|breadcrumbs; 1 tsp|garam masala; 1 handful|coriander; 2 tbsp|vegetable oil", "Mash the chickpeas and sweet potato flesh with the spice, coriander and salt / Mix in the breadcrumbs and shape 8 patties / Fry in the oil 3 to 4 minutes per side until crisp", 10),
    ("Lentil Walnut Burgers", "American", "250 g|green lentils, cooked; 80 g|walnuts, toasted; 60 g|rolled oats; 1|onion, grated; 1 tbsp|soy sauce; 1 tsp|smoked paprika; 4|burger buns", "Pulse the walnuts and oats fine, then add the lentils, onion, soy and paprika and pulse to a rough mix / Shape 4 patties and chill 15 minutes / Fry 4 minutes per side and serve in buns", 10),
    ("Mushroom and Lentil Shepherd's Pie (Vegan)", "British", "400 g|mushrooms, chopped; 400 g|brown lentils, cooked; 1|onion; 2|carrots, diced; 2 tbsp|tomato paste; 300 ml|vegetable stock; 1 kg|potatoes; 3 tbsp|olive oil", "Boil and mash the potatoes with 2 tbsp oil and salt / Fry the onion, carrot and mushrooms in the rest of the oil 10 minutes, add the paste, lentils and stock and simmer 10 minutes / Top with mash and bake at 200 °C for 25 minutes", 50),
    ("Stuffed Bell Peppers with Rice and Beans", "Mexican", "4|bell peppers, halved; 250 g|rice, cooked; 400 g|black beans, drained; 200 g|salsa; 1 tsp|cumin; 100 g|cheddar, grated", "Heat the oven to 200 °C / Mix the rice, beans, salsa, cumin and half the cheese and fill the peppers / Top with the rest of the cheese, cover with foil and bake 25 minutes, then uncover for 10", 35),
    ("Spinach and Ricotta Stuffed Shells", "Italian-American", "250 g|jumbo pasta shells; 500 g|ricotta; 200 g|spinach, wilted and chopped; 50 g|parmesan; 700 ml|marinara sauce; 125 g|mozzarella", "Cook the shells 2 minutes less than the pack says / Mix the ricotta, spinach, parmesan and salt and fill the shells / Spread sauce in a dish, add the shells, top with mozzarella and bake at 190 °C for 25 minutes", 35),
    ("Vegetable Lasagna with Zucchini and Spinach", "Italian", "12|lasagna sheets; 3|zucchini, sliced; 200 g|spinach; 500 g|ricotta; 700 ml|marinara sauce; 200 g|mozzarella; 50 g|parmesan", "Layer sauce, sheets, zucchini, spinach and ricotta three times / Finish with sauce, mozzarella and parmesan / Cover and bake at 190 °C for 30 minutes, uncover for 15", 45),
    ("White Bean and Kale Stew", "Italian", "800 g|cannellini beans, drained; 200 g|kale, chopped; 1|onion; 3|garlic cloves; 400 g|chopped tomatoes; 500 ml|vegetable stock; 1 sprig|rosemary; 3 tbsp|olive oil", "Soften the onion and garlic in the oil / Add the tomatoes, beans, stock and rosemary and simmer 15 minutes / Add the kale for 5 minutes and mash a few beans to thicken", 25),
    ("Tofu Tikka Masala", "British Indian", "400 g|firm tofu, cubed; 150 g|plain yogurt; 2 tbsp|tikka masala paste; 1|onion; 400 g|passata; 150 ml|heavy cream; 1 tbsp|vegetable oil", "Toss the tofu with the yogurt and half the paste and grill until charred / Fry the onion in the oil with the rest of the paste / Add the passata and cream, simmer 10 minutes and add the tofu", 25),
    ("Cauliflower Steaks with Chimichurri", "Argentine", "1|cauliflower, cut into 4 thick slices; 3 tbsp|olive oil; 1 large handful|parsley; 2|garlic cloves; 2 tbsp|red wine vinegar; 0.5 tsp|chili flakes", "Brush the cauliflower with 1 tbsp oil and salt and roast at 220 °C for 25 minutes, turning once / Chop the parsley and garlic and mix with the vinegar, chili and the rest of the oil / Spoon over the steaks", 25),
    ("Eggplant and Tomato Bake with Feta", "Greek", "2|eggplants, sliced; 4 tbsp|olive oil; 400 g|chopped tomatoes; 2|garlic cloves; 1 tsp|dried oregano; 150 g|feta", "Brush the eggplant with oil and roast at 220 °C for 20 minutes / Simmer the tomatoes, garlic and oregano 10 minutes / Layer in a dish, crumble over feta and bake 15 minutes", 45),
    ("Vegan Mushroom Bourguignon", "French", "750 g|mushrooms, halved; 200 g|pearl onions, peeled; 2|carrots; 2 tbsp|tomato paste; 500 ml|vegetable stock; 2 tbsp|soy sauce; 2 sprigs|thyme; 2 tbsp|olive oil; 1 tbsp|flour", "Brown the mushrooms in the oil in batches / Fry the onions and carrots 5 minutes, stir in the flour and paste / Add the stock, soy, thyme and mushrooms and simmer 30 minutes until thick", 45),
    ("Spiced Lentil and Spinach Soup (Vegan)", "Indian", "200 g|red lentils; 1|onion; 2|garlic cloves; 2 tsp|curry powder; 400 g|chopped tomatoes; 1 l|vegetable stock; 150 g|spinach; 1 tbsp|vegetable oil", "Soften the onion and garlic in the oil, add the curry powder / Add the lentils, tomatoes and stock and simmer 20 minutes / Stir in the spinach", 25),
    ("Butternut Squash Mac and Cheese", "American", "350 g|macaroni; 500 g|butternut squash, cubed; 300 ml|milk; 150 g|cheddar, grated; 1 tsp|dijon mustard; 30 g|butter", "Simmer the squash in the milk 15 minutes until soft and blend smooth / Cook the macaroni / Stir the cheese, mustard and butter into the squash sauce and toss with the pasta", 20),
    ("Vegan Black Bean Chili with Sweet Potato", "Tex-Mex", "800 g|black beans, drained; 2|sweet potatoes, cubed; 1|onion; 2|garlic cloves; 800 g|chopped tomatoes; 2 tbsp|chili powder; 1 tsp|cumin; 2 tbsp|olive oil", "Fry the onion and garlic in the oil, stir in the spices / Add the sweet potato, beans and tomatoes with 250 ml water and simmer 30 minutes", 35),
    ("Halloumi and Vegetable Skewers", "Cypriot", "250 g|halloumi, cubed; 2|bell peppers; 1|red onion; 1|zucchini; 3 tbsp|olive oil; 1|lemon; 1 tsp|dried oregano", "Thread the halloumi and chunks of veg on skewers / Brush with oil, lemon and oregano / Grill 8 to 10 minutes, turning, until charred", 10),
    ("Paneer Bhurji Wraps", "Indian", "250 g|paneer, crumbled; 1|onion; 2|tomatoes; 1|green chili; 0.5 tsp|turmeric; 1 tsp|garam masala; 4|flatbreads; 1 tbsp|vegetable oil", "Fry the onion and chili in the oil 5 minutes, add the tomatoes and spices for 3 minutes / Stir in the paneer and cook 3 minutes / Wrap in warm flatbreads", 12),
    ("Vegan Pad See Ew", "Thai", "400 g|wide rice noodles; 300 g|tofu, cubed; 300 g|chinese broccoli, chopped; 3|garlic cloves; 3 tbsp|soy sauce; 1 tbsp|dark soy sauce; 1 tbsp|sugar; 2 tbsp|vegetable oil", "Fry the tofu in the oil until golden / Add garlic and greens for 2 minutes / Add the noodles, sauces and sugar and toss over high heat until charred in places", 12),
    ("Vegetable Korma with Cashews", "Indian", "1|cauliflower, florets; 2|carrots; 200 g|peas; 1|onion; 80 g|cashews; 400 ml|coconut milk; 2 tbsp|korma paste; 1 tbsp|vegetable oil", "Blend the cashews with the coconut milk / Fry the onion in the oil with the paste / Add the vegetables and cashew milk and simmer 20 minutes", 25),
    ("Spanakorizo (Spinach Rice)", "Greek", "500 g|spinach; 200 g|long-grain rice; 1|onion; 4|spring onions; 1 handful|dill; 1|lemon; 4 tbsp|olive oil", "Soften the onions in the oil / Add the rice and 500 ml water and simmer 10 minutes / Add the spinach and dill, cover and cook 8 minutes. Finish with lemon", 20),
    ("Mujadara (Lentils and Rice with Crispy Onions)", "Lebanese", "200 g|brown lentils; 200 g|long-grain rice; 3|onions, thinly sliced; 5 tbsp|olive oil; 1 tsp|cumin", "Fry the onions in the oil over medium heat 25 minutes until deep brown / Simmer the lentils 15 minutes, add the rice, cumin and half the onions with 500 ml water and cook 15 minutes / Top with the rest of the onions", 45),
]:
    R(V, t, "Main", cu, 15, cook, 4, "Lunch, Dinner, Main dish", ings, st)

# ---- baking by grams (every dry ingredient weighed) ----
MUF = [("Banana Walnut", "2|bananas, mashed; 60 g|walnuts, chopped"), ("Carrot Spice", "150 g|carrots, grated; 1 tsp|mixed spice"), ("Apple Crumble", "1|apple, diced; 40 g|rolled oats"),
       ("Zucchini Chocolate Chip", "150 g|zucchini, grated; 80 g|chocolate chips"), ("Orange Almond", "1|orange, zested; 50 g|ground almonds"), ("Peach Ginger", "2|peaches, diced; 1 tsp|ground ginger")]
for n, extra in MUF:
    R(BK, "%s Muffins (by Weight)" % n, "Baking", "American", 15, 22, 12, "Breakfast, Snack, Baked goods",
      "250 g|flour; 10 g|baking powder; 3 g|salt; 130 g|sugar; 2|eggs; 220 g|milk; 90 g|vegetable oil; " + extra,
      ["Heat the oven to 200 °C (180 °C fan) and line a 12-hole muffin tin. Set a bowl on the scale and weigh as you go",
       "Whisk the flour, baking powder, salt and sugar (and any ground almonds, oats or spice)",
       "Weigh the milk and oil into a jug, then beat in the eggs. Pour onto the dry mix with the fruit, veg, nuts or chips and fold just until no dry flour shows",
       "Divide between the cases (about 75 g each) and bake 20 to 22 minutes until a skewer comes out clean"])
for t, cu, cook, serv, ings, st in [
    ("Rosemary Olive Oil Crackers", "Italian", 25, 8, "200 g|flour; 100 g|water; 40 g|olive oil; 4 g|salt; 1 tsp|rosemary, chopped", "Mix everything into a firm dough and rest 30 minutes / Roll very thin between baking paper, score into squares and prick / Bake at 180 °C for 20 to 25 minutes until crisp"),
    ("Same-Day Crusty White Loaf", "British", 35, 12, "500 g|bread flour; 350 g|water, warm; 7 g|instant yeast; 10 g|salt", "Mix to a shaggy dough, rest 20 minutes, then knead 8 minutes / Rise 1½ hours until doubled. Shape into a round and rise 45 minutes on a floured tray / Slash and bake at 230 °C for 30 to 35 minutes, until it sounds hollow underneath"),
    ("Overnight No-Knead Bread", "American", 45, 12, "500 g|bread flour; 375 g|water; 2 g|instant yeast; 10 g|salt", "Stir everything into a wet dough, cover and leave 12 to 18 hours at room temperature / Fold into a ball on a floured counter and rest 1 hour / Bake in a preheated lidded pot at 240 °C for 30 minutes, then 15 uncovered"),
    ("Whole Wheat Sandwich Bread", "American", 35, 12, "300 g|whole wheat flour; 200 g|bread flour; 340 g|water, warm; 30 g|honey; 30 g|butter, soft; 7 g|instant yeast; 9 g|salt", "Mix and knead 10 minutes until smooth / Rise 1 hour, shape into a 900 g loaf tin and rise 45 minutes / Bake at 200 °C for 30 to 35 minutes"),
    ("Rosemary Focaccia (by Weight)", "Italian", 25, 12, "500 g|bread flour; 400 g|water; 7 g|instant yeast; 10 g|salt; 50 g|olive oil; 2 sprigs|rosemary", "Mix the flour, water, yeast and salt into a sticky dough. Fold it over itself 4 times, 15 minutes apart / Rise 1 hour, then tip into an oiled tin, dimple with oily fingers and rise 45 minutes / Top with rosemary and a pinch more salt and bake at 220 °C for 22 to 25 minutes"),
    ("Milk Bread Rolls (Tangzhong)", "Japanese", 20, 12, "375 g|bread flour; 200 g|milk; 1|egg; 40 g|sugar; 30 g|butter, soft; 5 g|instant yeast; 5 g|salt", "Cook 25 g of the flour with 125 g of the milk, whisking, until a thick paste; cool / Knead it with everything else for 10 minutes until smooth / Rise 1 hour, divide into 12 balls (about 55 g each), rise 40 minutes and bake at 180 °C for 18 to 20 minutes"),
    ("Brown Butter Chocolate Chip Cookies (by Weight)", "American", 11, 18, "170 g|butter; 150 g|brown sugar; 50 g|sugar; 1|egg; 5 g|vanilla extract; 220 g|flour; 3 g|baking soda; 3 g|salt; 200 g|dark chocolate, chopped", "Brown the butter until nutty, then cool 10 minutes / Whisk in the sugars, egg and vanilla, then the flour, soda and salt, then the chocolate / Scoop 50 g balls and chill 30 minutes. Bake at 180 °C for 10 to 11 minutes"),
    ("Oat and Raisin Cookies (by Weight)", "British", 13, 16, "115 g|butter, soft; 150 g|brown sugar; 1|egg; 140 g|flour; 150 g|rolled oats; 3 g|baking soda; 3 g|cinnamon; 120 g|raisins", "Beat the butter and sugar, then the egg / Mix in everything else / Scoop 40 g balls onto lined trays and bake at 180 °C for 12 to 13 minutes"),
    ("Ginger Molasses Cookies", "American", 10, 20, "170 g|butter, soft; 200 g|sugar; 1|egg; 80 g|molasses; 280 g|flour; 6 g|baking soda; 6 g|ground ginger; 3 g|cinnamon", "Beat the butter and sugar, then the egg and molasses / Mix in the dry ingredients / Roll 35 g balls in sugar and bake at 180 °C for 10 minutes"),
    ("Almond Flour Shortbread", "Scottish", 15, 16, "150 g|almond flour; 100 g|flour; 120 g|butter, soft; 60 g|sugar; 1 pinch|salt", "Rub everything together into a dough / Press into a 20 cm tin and prick / Bake at 160 °C for 25 minutes; cut while warm"),
    ("Lemon Drizzle Loaf (by Weight)", "British", 45, 10, "175 g|butter, soft; 175 g|sugar; 3|eggs; 175 g|self-raising flour; 2|lemons; 100 g|powdered sugar", "Beat the butter and sugar, then the eggs one by one, then fold in the flour and lemon zest / Bake in a lined 900 g loaf tin at 180 °C for 40 to 45 minutes / Mix the lemon juice with the powdered sugar and pour over the hot cake"),
    ("Victoria Sponge (by Weight)", "British", 25, 8, "200 g|butter, soft; 200 g|sugar; 4|eggs; 200 g|self-raising flour; 2 tbsp|milk; 150 g|raspberry jam; 150 ml|heavy cream", "Beat the butter and sugar, add the eggs, then fold in the flour and milk / Divide between two lined 20 cm tins and bake at 180 °C for 22 to 25 minutes / Cool, then sandwich with jam and whipped cream"),
    ("Chocolate Olive Oil Cake", "Italian", 35, 10, "150 g|flour; 50 g|cocoa powder; 200 g|sugar; 5 g|baking soda; 3 g|salt; 120 g|olive oil; 240 g|water, hot; 1 tsp|vanilla extract; 1 tbsp|cider vinegar", "Whisk the dry ingredients / Whisk in the oil, hot water, vanilla and vinegar until smooth / Bake in a lined 20 cm tin at 180 °C for 30 to 35 minutes"),
    ("Carrot Cake (by Weight)", "American", 40, 12, "250 g|flour; 8 g|baking powder; 5 g|cinnamon; 200 g|brown sugar; 3|eggs; 200 g|vegetable oil; 300 g|carrots, grated; 80 g|walnuts; 200 g|cream cheese; 80 g|powdered sugar", "Whisk the flour, baking powder, cinnamon and sugar / Beat in the eggs and oil, fold in the carrots and walnuts / Bake in a lined 23 cm tin at 180 °C for 35 to 40 minutes. Beat the cream cheese with the powdered sugar and spread on the cooled cake"),
    ("Basque Burnt Cheesecake", "Spanish", 50, 10, "900 g|cream cheese; 250 g|sugar; 5|eggs; 400 g|heavy cream; 25 g|flour; 1 pinch|salt", "Line a 23 cm tin with two crumpled sheets of baking paper / Beat the cream cheese and sugar smooth, then the eggs one by one, then the cream, flour and salt / Bake at 220 °C for 45 to 50 minutes until very dark on top and wobbly in the middle. Cool, then chill"),
    ("Cinnamon Sugar Scones (by Weight)", "British", 15, 8, "350 g|self-raising flour; 85 g|butter, cold; 40 g|sugar; 175 g|milk; 1|egg; 5 g|cinnamon", "Rub the butter into the flour, sugar and cinnamon / Mix in the milk to a soft dough / Pat 3 cm thick, cut 8 rounds, brush with egg and bake at 220 °C for 12 to 15 minutes"),
    ("Cheese and Chive Scones", "British", 15, 8, "350 g|self-raising flour; 85 g|butter, cold; 100 g|cheddar, grated; 1 small bunch|chives, chopped; 175 g|milk; 1|egg", "Rub the butter into the flour with a pinch of salt / Stir in most of the cheese, the chives and milk / Pat 3 cm thick, cut 8 rounds, brush with egg, top with the rest of the cheese and bake at 220 °C for 12 to 15 minutes"),
    ("Soft Pretzels (by Weight)", "German", 14, 8, "500 g|bread flour; 300 g|water, warm; 7 g|instant yeast; 10 g|salt; 30 g|butter, soft; 60 g|baking soda; 1|egg", "Knead the flour, water, yeast, salt and butter 8 minutes and rise 1 hour / Divide into 8 (about 105 g), roll into ropes and twist / Dip each in 2 litres simmering water with the soda for 30 seconds / Brush with egg, sprinkle with a little extra salt and bake at 220 °C for 12 to 14 minutes"),
    ("Banana Bread (by Weight)", "American", 55, 10, "3|bananas, very ripe; 75 g|butter, melted; 150 g|brown sugar; 1|egg; 190 g|flour; 5 g|baking soda; 2 g|salt; 5 g|cinnamon", "Mash the bananas and mix with the butter, sugar and egg / Fold in the flour, soda, salt and cinnamon / Bake in a lined 900 g loaf tin at 175 °C for 50 to 55 minutes"),
    ("Gluten-Free Almond Orange Cake", "Spanish", 50, 10, "2|oranges; 6|eggs; 250 g|sugar; 250 g|ground almonds; 5 g|baking powder", "Simmer the whole oranges 1 hour until soft; cool and blend to a purée, removing seeds / Beat in the eggs, sugar, almonds and baking powder / Bake in a lined 23 cm tin at 180 °C for 45 to 50 minutes"),
    ("Pizza Dough (by Weight)", "Italian", 12, 4, "500 g|bread flour; 325 g|water; 3 g|instant yeast; 12 g|salt; 15 g|olive oil", "Mix and knead 8 minutes until smooth / Rise 2 hours (or overnight in the fridge) / Divide into 4 balls of about 210 g, rest 30 minutes, stretch thin and bake at the hottest oven setting for 8 to 12 minutes"),
    ("Brioche Burger Buns", "French", 18, 8, "500 g|bread flour; 7 g|instant yeast; 40 g|sugar; 8 g|salt; 4|eggs; 150 g|milk; 75 g|butter, soft", "Knead the flour, yeast, sugar, salt, 3 of the eggs and the milk 8 minutes, then knead in the butter / Rise 1½ hours, divide into 8 balls (about 110 g) and rise 1 hour / Brush with the last egg, beaten, and bake at 190 °C for 15 to 18 minutes"),
    ("Coconut Macaroons", "French", 18, 16, "200 g|desiccated coconut; 150 g|sweetened condensed milk; 2|egg whites; 1 pinch|salt; 1 tsp|vanilla extract", "Mix the coconut, condensed milk and vanilla / Whisk the whites with the salt to stiff peaks and fold in / Scoop 16 mounds and bake at 160 °C for 18 minutes"),
    ("Flapjacks (by Weight)", "British", 25, 12, "250 g|rolled oats; 125 g|butter; 125 g|brown sugar; 100 g|golden syrup; 1 pinch|salt", "Melt the butter, sugar and syrup / Stir in the oats and salt and press into a lined 20 cm tin / Bake at 180 °C for 20 to 25 minutes; cut while warm"),
]:
    R(BK, t, "Baking", cu, 20, cook, serv, "Baked goods, Snack" if "Bread" not in t and "Loaf" not in t else "Baked goods", ings, st)
